function gaussianBinomial(q, n, k):
    memo <- empty map
    function rec(n, k):
        if k = 0: return 1
        if n = 0: return 0
        if (n,k) in memo: return memo[(n,k)]
        v <- rec(n-1, k-1) + q^k * rec(n-1, k)
        memo[(n,k)] <- v
        return v
    return rec(n, k)

function linesOfPG3(q):
    return gaussianBinomial(q, 4, 2)   // = (q^2+1)(q^2+q+1)

